import { createRoute, z } from '@hono/zod-openapi'

const AutoChunkingStrategyRequestParamSchema = z
  .strictObject({
    type: z.literal('auto').openapi({ description: 'Always `auto`.', 'x-stainless-const': true }),
  })
  .openapi({
    title: 'Auto Chunking Strategy',
    description:
      'The default strategy. This strategy currently uses a `max_chunk_size_tokens` of `800` and `chunk_overlap_tokens` of `400`.',
    required: ['type'],
  })
  .openapi('AutoChunkingStrategyRequestParam')

const StaticChunkingStrategySchema = z
  .strictObject({
    max_chunk_size_tokens: z
      .int()
      .min(100)
      .max(4096)
      .openapi({
        description:
          'The maximum number of tokens in each chunk. The default value is `800`. The minimum value is `100` and the maximum value is `4096`.',
      }),
    chunk_overlap_tokens: z
      .int()
      .openapi({
        description:
          'The number of tokens that overlap between chunks. The default value is `400`.\n\nNote that the overlap must not exceed half of `max_chunk_size_tokens`.\n',
      }),
  })
  .openapi({ required: ['max_chunk_size_tokens', 'chunk_overlap_tokens'] })
  .openapi('StaticChunkingStrategy')

const StaticChunkingStrategyRequestParamSchema = z
  .strictObject({
    type: z
      .literal('static')
      .openapi({ description: 'Always `static`.', 'x-stainless-const': true }),
    static: StaticChunkingStrategySchema,
  })
  .openapi({
    title: 'Static Chunking Strategy',
    description: 'Customize your own chunking strategy by setting chunk size and chunk overlap.',
    required: ['type', 'static'],
  })
  .openapi('StaticChunkingStrategyRequestParam')

type ChunkingStrategyRequestParamType =
  | z.infer<typeof AutoChunkingStrategyRequestParamSchema>
  | z.infer<typeof StaticChunkingStrategyRequestParamSchema>

const ComparisonFilterSchema = z
  .strictObject({
    type: z
      .enum(['eq', 'ne', 'gt', 'gte', 'lt', 'lte', 'in', 'nin'])
      .default('eq')
      .openapi({
        description:
          'Specifies the comparison operator: `eq`, `ne`, `gt`, `gte`, `lt`, `lte`, `in`, `nin`.\n- `eq`: equals\n- `ne`: not equal\n- `gt`: greater than\n- `gte`: greater than or equal\n- `lt`: less than\n- `lte`: less than or equal\n- `in`: in\n- `nin`: not in\n',
      }),
    key: z.string().openapi({ description: 'The key to compare against the value.' }),
    value: z
      .xor([z.string(), z.number(), z.boolean(), z.array(z.xor([z.string(), z.number()]))])
      .openapi({
        description:
          'The value to compare against the attribute key; supports string, number, or boolean types.',
      }),
  })
  .openapi({
    title: 'Comparison Filter',
    description:
      'A filter used to compare a specified attribute key to a given value using a defined comparison operation.\n',
    required: ['type', 'key', 'value'],
    'x-oaiMeta': { name: 'ComparisonFilter' },
  })
  .openapi('ComparisonFilter')

type CompoundFilterType = {
  type: 'and' | 'or'
  filters: (z.infer<typeof ComparisonFilterSchema> | CompoundFilterType)[]
}

const PromptCacheBreakpointConfigSchema = z
  .object({
    mode: z
      .literal('explicit')
      .default('explicit')
      .openapi({
        description: 'The breakpoint mode. Always `explicit`.',
        'x-stainless-const': true,
      }),
  })
  .openapi({
    required: ['mode'],
    title: 'Prompt cache breakpoint',
    description:
      "Marks the exact end of a reusable prompt prefix. The breakpoint inherits its TTL from the request's `prompt_cache_options.ttl`; the boundary is not rounded to a token block.",
  })
  .openapi('PromptCacheBreakpointConfig')

const InputTextContentSchema = z
  .object({
    type: z
      .literal('input_text')
      .default('input_text')
      .openapi({
        description: 'The type of the input item. Always `input_text`.',
        'x-stainless-const': true,
      }),
    text: z.string().openapi({ description: 'The text input to the model.' }),
    prompt_cache_breakpoint: PromptCacheBreakpointConfigSchema.exactOptional(),
  })
  .openapi({
    required: ['type', 'text'],
    title: 'Input text',
    description: 'A text input to the model.',
  })
  .openapi('InputTextContent')

const ImageDetailSchema = z.enum(['low', 'high', 'auto', 'original']).openapi('ImageDetail')

const InputImageContentSchema = z
  .object({
    type: z
      .literal('input_image')
      .default('input_image')
      .openapi({
        description: 'The type of the input item. Always `input_image`.',
        'x-stainless-const': true,
      }),
    image_url: z
      .union([
        z
          .url()
          .openapi({
            description:
              'The URL of the image to be sent to the model. A fully qualified URL or base64 encoded image in a data URL.',
          }),
        z.null().nullable(),
      ])
      .exactOptional(),
    file_id: z
      .union([
        z.string().openapi({ description: 'The ID of the file to be sent to the model.' }),
        z.null().nullable(),
      ])
      .exactOptional(),
    detail: ImageDetailSchema.openapi({
      description:
        'The detail level of the image to be sent to the model. One of `high`, `low`, `auto`, or `original`. Defaults to `auto`.',
    }),
    prompt_cache_breakpoint: PromptCacheBreakpointConfigSchema.exactOptional(),
  })
  .openapi({
    required: ['type', 'detail'],
    title: 'Input image',
    description:
      'An image input to the model. Learn about [image inputs](https://developers.openai.com/api/docs/guides/images-vision).',
  })
  .openapi('InputImageContent')

const FileInputDetailSchema = z.enum(['auto', 'low', 'high']).openapi('FileInputDetail')

const InputFileContentSchema = z
  .object({
    type: z
      .literal('input_file')
      .default('input_file')
      .openapi({
        description: 'The type of the input item. Always `input_file`.',
        'x-stainless-const': true,
      }),
    file_id: z
      .union([
        z.string().openapi({ description: 'The ID of the file to be sent to the model.' }),
        z.null().nullable(),
      ])
      .exactOptional(),
    filename: z
      .string()
      .exactOptional()
      .openapi({ description: 'The name of the file to be sent to the model.' }),
    file_data: z
      .string()
      .exactOptional()
      .openapi({ description: 'The content of the file to be sent to the model.\n' }),
    prompt_cache_breakpoint: PromptCacheBreakpointConfigSchema.exactOptional(),
    file_url: z
      .url()
      .exactOptional()
      .openapi({ description: 'The URL of the file to be sent to the model.' }),
    detail: FileInputDetailSchema.exactOptional().openapi({
      description:
        'The detail level of the file to be sent to the model. Use `auto` to let the system select the detail level; for GPT-5.6 and later models, `auto` uses high-quality rendering, which may increase input token usage. Use `low` for lower-cost rendering, or `high` to render the file at higher quality. Defaults to `auto`.',
    }),
  })
  .openapi({ required: ['type'], title: 'Input file', description: 'A file input to the model.' })
  .openapi('InputFileContent')

const InputContentSchema = z
  .discriminatedUnion('type', [
    InputTextContentSchema,
    InputImageContentSchema,
    InputFileContentSchema,
  ])
  .openapi({ discriminator: { propertyName: 'type' } })
  .openapi('InputContent')

const FileCitationBodySchema = z
