type ContentType = z.infer<typeof InputContentSchema> | z.infer<typeof OutputContentSchema>

const ToolCallCallerParamSchema: z.ZodType<ToolCallCallerParamType> = z
  .lazy(() =>
    z
      .discriminatedUnion('type', [
        DirectToolCallCallerParamSchema,
        ProgramToolCallCallerParamSchema,
      ])
      .openapi({
        description: 'The execution context that produced this tool call.',
        discriminator: { propertyName: 'type' },
      }),
  )
  .openapi('ToolCallCallerParam')

const FunctionAndCustomToolCallOutputSchema = z
  .discriminatedUnion('type', [
    InputTextContentSchema,
    InputImageContentSchema,
    InputFileContentSchema,
  ])
  .openapi({ discriminator: { propertyName: 'type' } })
  .openapi('FunctionAndCustomToolCallOutput')

type CustomToolCallOutputType = {
  type: 'custom_tool_call_output'
  id?: string
  call_id: string
  caller?: z.infer<typeof ToolCallCallerParamSchema> | ({ [key: string]: unknown } | null)
  output: string | z.infer<typeof FunctionAndCustomToolCallOutputSchema>[]
}

const InputMessageContentListSchema = z
  .array(InputContentSchema)
  .openapi({
    title: 'Input item content list',
    description:
      'A list of one or many input items to the model, containing different content \ntypes.\n',
  })
  .openapi('InputMessageContentList')

const InputMessageSchema = z
  .object({
    type: z
      .literal('message')
      .exactOptional()
      .openapi({
        description: 'The type of the message input. Always set to `message`.\n',
        'x-stainless-const': true,
      }),
    role: z
      .enum(['user', 'system', 'developer'])
      .openapi({
        description: 'The role of the message input. One of `user`, `system`, or `developer`.\n',
      }),
    status: z
      .enum(['in_progress', 'completed', 'incomplete'])
      .exactOptional()
      .openapi({
        description:
          'The status of item. One of `in_progress`, `completed`, or\n`incomplete`. Populated when items are returned via API.\n',
      }),
    content: InputMessageContentListSchema,
  })
  .openapi({
    title: 'Input message',
    description:
      'A message input to the model with a role indicating instruction following\nhierarchy. Instructions given with the `developer` or `system` role take\nprecedence over instructions given with the `user` role.\n',
    required: ['role', 'content'],
  })
  .openapi('InputMessage')

const OutputMessageContentSchema = z
  .discriminatedUnion('type', [OutputTextContentSchema, RefusalContentSchema])
  .openapi({ discriminator: { propertyName: 'type' } })
  .openapi('OutputMessageContent')

const MessagePhaseSchema = z
  .enum(['commentary', 'final_answer'])
  .openapi({
    description:
      'Labels an `assistant` message as intermediate commentary (`commentary`) or the final answer (`final_answer`).\nFor models like `gpt-5.3-codex` and beyond, when sending follow-up requests, preserve and resend\nphase on all assistant messages — dropping it can degrade performance. Not used for user messages.\n',
  })
  .openapi('MessagePhase')

const OutputMessageSchema = z
  .object({
    id: z.string().openapi({ description: 'The unique ID of the output message.\n' }),
    type: z
      .literal('message')
      .openapi({
        description: 'The type of the output message. Always `message`.\n',
        'x-stainless-const': true,
      }),
    role: z
      .literal('assistant')
      .openapi({
        description: 'The role of the output message. Always `assistant`.\n',
        'x-stainless-const': true,
      }),
    content: z
      .array(OutputMessageContentSchema)
      .openapi({ description: 'The content of the output message.\n' }),
    phase: z.union([MessagePhaseSchema, z.null().nullable()]).exactOptional(),
    status: z
      .enum(['in_progress', 'completed', 'incomplete'])
      .openapi({
        description:
          'The status of the message input. One of `in_progress`, `completed`, or\n`incomplete`. Populated when input items are returned via API.\n',
      }),
  })
  .openapi({
    title: 'Output message',
    description: 'An output message from the model.\n',
    required: ['id', 'type', 'role', 'content', 'status'],
  })
  .openapi('OutputMessage')

const VectorStoreFileAttributesSchema = z
  .union([
    z
      .record(z.string(), z.xor([z.string().max(512), z.number(), z.boolean()]))
      .refine((val) => Object.keys(val).length <= 16)
      .openapi({
        description:
          'Set of 16 key-value pairs that can be attached to an object. This can be\nuseful for storing additional information about the object in a structured\nformat, and querying for objects via API or the dashboard. Keys are strings\nwith a maximum length of 64 characters. Values are strings with a maximum\nlength of 512 characters, booleans, or numbers.\n',
        'x-oaiTypeLabel': 'map',
      }),
    z.null().nullable(),
  ])
  .openapi('VectorStoreFileAttributes')

const FileSearchToolCallSchema = z
  .object({
    id: z.string().openapi({ description: 'The unique ID of the file search tool call.\n' }),
    type: z
      .literal('file_search_call')
      .openapi({
        description: 'The type of the file search tool call. Always `file_search_call`.\n',
        'x-stainless-const': true,
      }),
    status: z
      .enum(['in_progress', 'searching', 'completed', 'incomplete', 'failed'])
      .openapi({
        description:
          'The status of the file search tool call. One of `in_progress`,\n`searching`, `incomplete` or `failed`,\n',
      }),
    queries: z
      .array(z.string())
      .openapi({ description: 'The queries used to search for files.\n' }),
    results: z
      .union([
        z
          .array(
            z
              .object({
                file_id: z
                  .string()
                  .exactOptional()
                  .openapi({ description: 'The unique ID of the file.\n' }),
                text: z
                  .string()
                  .exactOptional()
                  .openapi({ description: 'The text that was retrieved from the file.\n' }),
                filename: z
                  .string()
                  .exactOptional()
                  .openapi({ description: 'The name of the file.\n' }),
                attributes: VectorStoreFileAttributesSchema.exactOptional(),
                score: z
                  .float32()
                  .exactOptional()
                  .openapi({
                    description: 'The relevance score of the file - a value between 0 and 1.\n',
                  }),
              })
              .openapi({ required: [] }),
          )
          .openapi({ description: 'The results of the file search tool call.\n' }),
        z.null().nullable(),
      ])
      .exactOptional(),
  })
  .openapi({
    title: 'File search tool call',
    description:
      'The results of a file search tool call. See the\n[file search guide](https://developers.openai.com/api/docs/guides/tools-file-search) for more information.\n',
    required: ['id', 'type', 'status', 'queries'],
  })
  .openapi('FileSearchToolCall')

