const LiveReasoningSummarySchema = z
  .enum(['concise', 'detailed', 'auto'])
  .openapi('LiveReasoningSummary')

const LiveDelegationReasoningInputParamSchema = z
  .object({
    effort: z
      .union([
        LiveReasoningEffortSchema.openapi({
          description:
            'How much reasoning effort the delegated Responses model should use. Supported values depend on the backend model.',
        }),
        z.null().nullable(),
      ])
      .exactOptional(),
    summary: z
      .union([
        LiveReasoningSummarySchema.openapi({
          description:
            'The reasoning summary to request from the delegated Responses model, when supported.',
        }),
        z.null().nullable(),
      ])
      .exactOptional(),
  })
  .openapi({
    description: 'Reasoning options for Responses requests made on behalf of the Live session.',
    required: [],
  })
  .openapi('LiveDelegationReasoningInputParam')

const LiveTextVerbositySchema = z.enum(['low', 'medium', 'high']).openapi('LiveTextVerbosity')

