const BetaMisalignmentSteerSchema = z
  .object({ message: z.string().openapi({ description: 'The public continuation instruction.' }) })
  .openapi({ required: ['message'] })
  .openapi('BetaMisalignmentSteer')

const BetaMisalignmentErrorDetailsResourceSchema = z
  .object({
    review_target: z
      .union([
        z
          .string()
          .regex(/^[A-Za-z0-9._~:-]+$/)
          .min(1)
          .max(96)
          .refine(
            (val) =>
              !z
                .unknown()
                .superRefine((val, ctx) => {
                  if (typeof val === 'string') {
                    if (!new RegExp('[^A-Za-z0-9._~:-]').test(val)) {
                      ctx.addIssue({ code: 'custom' })
                    }
                  }
                })
                .safeParse(val).success,
          )
          .openapi({
            description:
              'An opaque target for explicitly continuing this review, or null when unavailable.',
          }),
        z.null().nullable(),
      ])
      .exactOptional(),
    error_type: BetaMisalignmentErrorTypeSchema.exactOptional().openapi({
      description: 'An optional classification; clients must accept additional values.',
    }),
    detailed_explanation: z
      .string()
      .exactOptional()
      .openapi({ description: 'The public explanation for this block.' }),
    steer: BetaMisalignmentSteerSchema.exactOptional().openapi({
      description: 'An optional public continuation instruction.',
    }),
  })
  .openapi({ required: [] })
  .openapi('BetaMisalignmentErrorDetailsResource')

