export const postLiveSessionsRoute = createRoute({
  method: 'post',
  path: '/live/sessions',
  tags: ['Live'],
  summary: 'Create session',
  description:
    'Create a Live WebRTC session or place an outbound SIP call. Start with the\n[Live prompting guide](https://developers.openai.com/api/docs/guides/live-prompting) for session configuration\nand [Telephony and SIP](https://developers.openai.com/api/docs/guides/voice-sip?api=live#place-an-outbound-call)\nfor trunk setup and call monitoring.\n\nSet transport.type to `webrtc` and supply an SDP offer, or set it to `sip`\nand supply an E.164 destination and trunk credentials. Outbound SIP calling\nmust be enabled for your organization.\nRinging is limited to 3 minutes and connected calls to 2 hours; these limits\nare not configurable in the request.\n\nReturns `201 Created` after session initialization. WebRTC responses include an\nSDP answer. SIP responses do not wait for the callee to answer. Attach a\nsideband connection using session.id to monitor SIP call progress.\n\nEach SIP request creates a new call. If a request times out or the connection\nfails, retry with caution: the original request may have succeeded, and a\nretry can place another call.',
  operationId: 'create-live',
  request: {
    body: {
      content: { 'application/json': { schema: LiveSessionCreateRequestSchema } },
      required: true,
    },
  },
  responses: {
    201: {
      description:
        'Returns 201 Created with a WebRTC answer or an initialized outbound SIP session. A SIP response does not mean the callee has answered.',
      content: {
        'application/json': {
          schema: LiveSessionCreateResponseSchema,
          examples: {
            webrtc: {
              summary: 'WebRTC session created (201 Created)',
              value: {
                session: { id: 'live_123' },
                transport: { type: 'webrtc', sdp: '<SDP answer>' },
              },
            },
            sip: {
              summary: 'Outbound SIP session initialized (201 Created)',
              value: { session: { id: 'live_123' }, transport: { type: 'sip' } },
            },
          },
        },
      },
    },
    400: {
      description: 'Invalid Live session request.',
      content: {
        'application/json': { schema: ErrorResponseSchema },
        'text/plain': { schema: z.string() },
      },
    },
    413: {
      description: 'The Live session request exceeds the supported size limit.',
      content: {
        'application/json': { schema: ErrorResponseSchema },
        'text/plain': { schema: z.string() },
      },
    },
    429: {
      description: 'The session could not start because a rate or quota limit was exceeded.',
      content: { 'application/json': { schema: ErrorResponseSchema } },
    },
    500: {
      description: 'An internal error occurred. The response body is plain text.',
      content: { 'text/plain': { schema: z.string() } },
    },
    502: {
      description: 'The SIP gateway could not initialize the outbound call.',
      content: { 'text/plain': { schema: z.string() } },
    },
    503: {
      description: 'The session is temporarily unavailable.',
      content: {
        'application/json': { schema: ErrorResponseSchema },
        'text/plain': { schema: z.string() },
      },
    },
    504: {
      description: 'SIP session initialization timed out. The error code is sip_setup_timeout.',
      content: { 'application/json': { schema: ErrorResponseSchema } },
    },
  },
})

