export const postResponsesRoute = createRoute({
  method: 'post',
  path: '/responses',
  tags: ['Responses'],
  summary: 'Create a model response',
  description:
    "Creates a model response. Provide [text](https://developers.openai.com/api/docs/guides/text) or\n[image](https://developers.openai.com/api/docs/guides/images-vision) inputs to generate [text](https://developers.openai.com/api/docs/guides/text)\nor [JSON](https://developers.openai.com/api/docs/guides/structured-outputs) outputs. Have the model call\nyour own [custom code](https://developers.openai.com/api/docs/guides/function-calling) or use built-in\n[tools](https://developers.openai.com/api/docs/guides/tools) like [web search](https://developers.openai.com/api/docs/guides/tools-web-search)\nor [file search](https://developers.openai.com/api/docs/guides/tools-file-search) to use your own data\nas input for the model's response.\n",
  operationId: 'createResponse',
  request: {
    body: { content: { 'application/json': { schema: CreateResponseSchema } }, required: true },
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': { schema: ResponseSchema },
        'text/event-stream': { schema: ResponseStreamEventSchema },
      },
    },
    400: {
      description: 'Invalid response request or incompatible request parameters.',
      content: { 'application/json': { schema: ErrorResponseSchema } },
    },
    404: {
      description:
        'The requested model or a referenced resource was not found or is unavailable to this caller.',
      content: { 'application/json': { schema: ErrorResponseSchema } },
    },
    429: InferenceRateLimitedResponse,
    503: InferenceServiceUnavailableResponse,
  },
})

export const getResponsesResponseIdRoute = createRoute({
  method: 'get',
  path: '/responses/{response_id}',
  tags: ['Responses'],
  summary: 'Get a model response',
  description: 'Retrieves a model response with the given ID.\n',
  operationId: 'getResponse',
  request: {
    params: z.object({
      response_id: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'response_id',
            required: true,
            schema: { type: 'string', example: 'resp_677efb5139a88190b512bc3fef8e535d' },
            description: 'The ID of the response to retrieve.',
          },
          example: 'resp_677efb5139a88190b512bc3fef8e535d',
        }),
    }),
    query: z.object({
      include: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(IncludeEnumSchema),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'include',
            schema: { type: 'array', items: { $ref: '#/components/schemas/IncludeEnum' } },
            description:
              'Additional fields to include in the response. See the `include`\nparameter for Response creation above for more information.\n',
            required: false,
          },
        }),
      stream: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'stream',
            schema: { type: 'boolean' },
            description:
              'If set to true, the model response data will be streamed to the client\nas it is generated using [server-sent events](https://developer.mozilla.org/en-US/docs/Web/API/Server-sent_events/Using_server-sent_events#Event_stream_format).\nSee the [Streaming section below](https://developers.openai.com/api/reference/resources/responses/streaming-events)\nfor more information.\n',
            required: false,
          },
        }),
      starting_after: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'starting_after',
            schema: { type: 'integer' },
            description: 'The sequence number of the event after which to start streaming.\n',
            required: false,
          },
        }),
      include_obfuscation: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'include_obfuscation',
            schema: { type: 'boolean' },
            description:
              'When true, stream obfuscation will be enabled. Stream obfuscation adds\nrandom characters to an `obfuscation` field on streaming delta events\nto normalize payload sizes as a mitigation to certain side-channel\nattacks. These obfuscation fields are included by default, but add a\nsmall amount of overhead to the data stream. You can set\n`include_obfuscation` to false to optimize for bandwidth if you trust\nthe network links between your application and the OpenAI API.\n',
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': { schema: ResponseSchema },
        'text/event-stream': { schema: ResponseStreamEventSchema },
      },
    },
    404: {
      description: 'The response was not found.',
      content: { 'application/json': { schema: ErrorResponseSchema } },
    },
    429: TooManyRequestsResponse,
  },
})

