export const postContentProvenanceChecksRoute = createRoute({
  method: 'post',
  path: '/content_provenance_checks',
  summary: 'Create content provenance check',
  description:
    "Check whether an image or audio file contains known OpenAI provenance signals. [Learn more about content provenance](https://developers.openai.com/api/docs/guides/content-provenance).\n\nIf `not_detected`, it means the tool did not find supported signals in the uploaded file. The content could still have been generated by OpenAI if the metadata was stripped or has evidence of tampering, the watermark was degraded, it comes from a legacy generation model, or it was created before provenance signals were available. Content could also still be AI-generated by another company's model, which the tool currently does not detect.",
  operationId: 'Createcontentprovenancecheck',
  request: {
    body: { content: { 'multipart/form-data': { schema: CreateContentProvenanceBodySchema } } },
  },
  responses: {
    200: {
      description: 'Success',
      content: { 'application/json': { schema: ProvenanceResourceSchema } },
    },
    400: {
      description:
        'The file is missing, invalid, unsupported, too large, or rejected by safety checks.',
      content: { 'application/json': { schema: ErrorResponseSchema } },
    },
    404: {
      description: 'Content provenance checks are unavailable to this caller.',
      content: { 'application/json': { schema: ErrorResponseSchema } },
    },
    429: TooManyRequestsResponse,
    500: {
      description: 'The content provenance check could not be completed.',
      content: { 'application/json': { schema: ErrorResponseSchema } },
    },
    503: {
      description: 'Content provenance inspection is temporarily unavailable.',
      content: { 'application/json': { schema: ErrorResponseSchema } },
    },
  },
})

export const getVideosRoute = createRoute({
  method: 'get',
  path: '/videos',
  tags: ['Videos'],
  summary: 'List videos',
  description: 'List recently generated videos for the current project.',
  operationId: 'ListVideos',
  request: {
    query: z.object({
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(0).max(100),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            description: 'Number of items to retrieve',
            required: false,
            schema: { type: 'integer', minimum: 0, maximum: 100 },
          },
        }),
      order: OrderEnumSchema.openapi({
        param: {
          name: 'order',
          in: 'query',
          description:
            'Sort order of results by timestamp. Use `asc` for ascending order or `desc` for descending order.',
          required: false,
          schema: { $ref: '#/components/schemas/OrderEnum' },
        },
      }).exactOptional(),
      after: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'after',
            in: 'query',
            description: 'Identifier for the last item from the previous pagination request',
            required: false,
            schema: {
              description: 'Identifier for the last item from the previous pagination request',
              type: 'string',
            },
          },
          description: 'Identifier for the last item from the previous pagination request',
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success',
      content: { 'application/json': { schema: VideoListResourceSchema } },
    },
    400: {
      description:
        'The query parameters are invalid, or the organization does not support video generation.',
      content: { 'application/json': { schema: ErrorResponseSchema } },
    },
    404: {
      description:
        'The video specified by after was not found or is not accessible, or the Videos API is unavailable.',
      content: { 'application/json': { schema: ErrorResponseSchema } },
    },
  },
  deprecated: true,
})

