export const postSkillsSkillIdVersionsRoute = createRoute({
  method: 'post',
  path: '/skills/{skill_id}/versions',
  tags: ['Skills'],
  summary: 'Create Skill Version',
  description: 'Create a new immutable skill version.',
  operationId: 'CreateSkillVersion',
  request: {
    params: z.object({
      skill_id: z
        .string()
        .openapi({
          param: {
            name: 'skill_id',
            in: 'path',
            description: 'The identifier of the skill to version.',
            required: true,
            schema: { example: 'skill_123', type: 'string' },
          },
          example: 'skill_123',
        }),
    }),
    body: {
      content: {
        'multipart/form-data': {
          schema: z
            .object({
              files: z.xor([
                z
                  .preprocess(
                    (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                    z.array(z.file().openapi({ type: 'string', format: 'binary' })).max(500),
                  )
                  .openapi({
                    description: 'Skill files to upload (directory upload) or a single zip file.',
                  }),
                z
                  .file()
                  .openapi({
                    type: 'string',
                    format: 'binary',
                    description: 'Skill zip file to upload.',
                  }),
              ]),
              default: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional()
                .openapi({ description: 'Whether to set this version as the default.' }),
            })
            .openapi({
              required: ['files'],
              title: 'Create skill version request',
              description: 'Uploads a new immutable version of a skill.',
            }),
        },
        'application/json': { schema: CreateSkillVersionBodySchema },
      },
    },
  },
  responses: {
    200: {
      description: 'Success',
      content: { 'application/json': { schema: SkillVersionResourceSchema } },
    },
    400: {
      description: 'The uploaded skill files or archive are invalid.',
      content: { 'application/json': { schema: ErrorResponseSchema } },
    },
    404: {
      description: 'The skill was not found.',
      content: { 'application/json': { schema: ErrorResponseSchema } },
    },
    429: TooManyRequestsResponse,
    500: {
      description: 'The skill version could not be saved.',
      content: { 'application/json': { schema: ErrorResponseSchema } },
    },
  },
})

