export const getVaultsRoute = createRoute({
  method: 'get',
  path: '/vaults',
  tags: ['Vaults'],
  summary: 'List vaults',
  description:
    'Lists vaults using ID-based pagination. See [vaults](https://developers.openai.com/api/docs/guides/agents-api/tools/vaults).',
  operationId: 'listVaults',
  request: {
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const isGroup = (item: unknown): item is Record<string, unknown> =>
          typeof item === 'object' && item !== null && !Array.isArray(item)
        const lists = new WeakSet<object>()
        const isIndex = (part: string | undefined) => part !== undefined && /^\d*$/.test(part)
        const child = (target: Record<string, unknown>, key: string, asList: boolean) => {
          const held = target[key]
          if (isGroup(held)) return held
          const made: Record<string, unknown> = Object.create(null)
          if (asList) lists.add(made)
          target[key] = made
          return made
        }
        const set = (
          root: Record<string, unknown>,
          path: readonly string[],
          item: unknown,
        ): void => {
          const work: [Record<string, unknown>, number, unknown, boolean][] = [
            [root, 0, item, false],
          ]
          for (let job = work.pop(); job !== undefined; job = work.pop()) {
            const [target, at, value, split] = job
            const head = path[at]
            if (head === undefined) continue
            const next = path[at + 1]
            if (head === '') {
              if (!split && Array.isArray(value)) {
                for (let i = value.length - 1; i >= 0; i -= 1)
                  work.push([target, at, value[i], true])
                continue
              }
              const size = Object.keys(target).length
              if (next === undefined) {
                target[String(size)] = value
                continue
              }
              const free =
                next === ''
                  ? -1
                  : Object.values(target).findIndex((held) => isGroup(held) && !(next in held))
              work.push([
                child(target, String(free < 0 ? size : free), isIndex(next)),
                at + 1,
                value,
                false,
              ])
              continue
            }
            if (next === undefined) {
              target[head] = value
              continue
            }
            work.push([child(target, head, isIndex(next)), at + 1, value, false])
          }
        }
        const settle = (root: unknown): unknown => {
          if (!isGroup(root)) return root
          const found: [Record<string, unknown>, string, Record<string, unknown>][] = []
          const queue: Record<string, unknown>[] = [root]
          for (const node of queue) {
            for (const [key, inner] of Object.entries(node)) {
              if (isGroup(inner)) {
                found.push([node, key, inner])
                queue.push(inner)
              }
            }
          }
          const finish = (group: Record<string, unknown>): unknown =>
            lists.has(group)
              ? Object.entries(group)
                  .sort((a, b) => Number(a[0]) - Number(b[0]))
                  .map(([, inner]) => inner)
              : Object.assign(Object.create(null), group)
          for (const [parent, key, group] of found.reverse()) {
            parent[key] = finish(group)
          }
          return finish(root)
        }
        const deep: string[] = ['metadata']
        for (const [key, item] of Object.entries(val)) {
          const match = /^([^\[\]]+)((?:\[[^\[\]]*\])+)$/.exec(key)
          const name = match?.[1]
          const path = match?.[2]
          if (name !== undefined && path !== undefined && deep.includes(name)) {
            const parts = path.slice(1, -1).split('][')
            set(group(name), parts, item)
            continue
          }
          rest.push([key, item])
        }
        return Object.fromEntries([
          ...rest,
          ...[...groups].map(([name, held]) => [name, settle(held)] as const),
        ])
      })
      .pipe(
        z.object({
          limit: z
            .preprocess((val) => {
              if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
                return val
              if (/^-?\d+$/.test(val)) return BigInt(val)
              const num = Number(val)
              return Number.isSafeInteger(num) ? BigInt(num) : val
            }, z.int64().min(1n).max(100n))
            .default(20n)
            .exactOptional()
            .openapi({
              param: {
                name: 'limit',
                in: 'query',
                required: false,
                schema: { type: 'integer', format: 'int64', minimum: 1, maximum: 100, default: 20 },
                description:
                  'The maximum number of resources to return, between 1 and 100. Defaults to 20.',
              },
            }),
          order: z
            .enum(['asc', 'desc'])
            .default('desc')
            .exactOptional()
            .openapi({
              param: {
                name: 'order',
                in: 'query',
                required: false,
                schema: {
                  type: 'string',
                  enum: ['asc', 'desc'],
                  'x-enumDescriptions': [
                    'Returns resources in ascending order.',
                    'Returns resources in descending order.',
                  ],
                  description: 'The order in which paginated resources are returned.',
                  default: 'desc',
                },
                description: 'The order in which resources are returned. Defaults to `desc`.',
              },
              'x-enumDescriptions': [
                'Returns resources in ascending order.',
                'Returns resources in descending order.',
              ],
              description: 'The order in which paginated resources are returned.',
            }),
          after: z
            .string()
            .min(0)
            .max(1048576)
            .exactOptional()
            .openapi({
              param: {
                name: 'after',
                in: 'query',
                required: false,
                schema: { type: 'string', minLength: 0, maxLength: 1048576 },
                description: 'Return resources after this resource ID in the selected order.',
              },
            }),
          metadata: z
            .record(z.string(), z.string().min(0).max(512))
            .refine((val) => Object.keys(val).length >= 0)
            .refine((val) => Object.keys(val).length <= 16)
            .exactOptional()
            .openapi({
              param: {
                name: 'metadata',
                in: 'query',
                required: false,
                schema: {
                  type: 'object',
                  additionalProperties: { type: 'string', minLength: 0, maxLength: 512 },
                  propertyNames: { type: 'string', minLength: 1, maxLength: 64 },
                  minProperties: 0,
                  maxProperties: 16,
                },
                description:
                  'Exact string matches supplied as `metadata[key]=value`. All supplied pairs must match. Up to 16 pairs, with keys from 1 to 64 characters and values up to 512 characters. Filtering is eventually consistent; metadata changes may take time to appear.',
                style: 'deepObject',
                explode: true,
              },
            }),
          status: VaultStatusFilterParamSchema.openapi({
            param: {
              name: 'status',
              in: 'query',
              required: false,
              schema: { $ref: '#/components/schemas/VaultStatusFilterParam' },
              description:
                'Filter by one status or a list, such as `status=active` or `status[]=active&status[]=archived`. Both statuses are included by default.',
            },
          }).exactOptional(),
        }),
      ),
  },
  responses: {
    200: {
      description: 'A page of vaults.',
      content: {
        'application/json': {
          schema: VaultListResourceSchema.openapi({ description: 'A page of vaults.' }),
        },
      },
    },
    400: {
      description: 'The request was invalid.',
      content: { 'application/json': { schema: ErrorResponse_2Schema } },
    },
    401: {
      description: 'Authentication or project context was missing.',
      content: { 'application/json': { schema: ErrorResponse_2Schema } },
    },
    403: {
      description: 'The API key lacks the required management permission.',
      content: { 'application/json': { schema: ErrorResponse_2Schema } },
    },
    404: {
      description: 'The requested vault or credential was not found.',
      content: { 'application/json': { schema: ErrorResponse_2Schema } },
    },
    409: {
      description: 'The request conflicted with the current vault state.',
      content: { 'application/json': { schema: ErrorResponse_2Schema } },
    },
    500: {
      description: 'An internal error occurred.',
      content: { 'application/json': { schema: ErrorResponse_2Schema } },
    },
    503: {
      description: 'The service is temporarily unavailable.',
      content: { 'application/json': { schema: ErrorResponse_2Schema } },
    },
  },
})

