export const getWebhookEndpointsRoute = createRoute({
  method: 'get',
  path: '/webhook_endpoints',
  summary: 'List Webhook Endpoints',
  description: 'Returns webhook endpoints for the authenticated project in newest-first order.',
  operationId: 'ListWebhookEndpoints',
  request: {
    query: z.object({
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(100),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            description: 'Maximum number of webhook endpoints to return. Defaults to 20.',
            required: false,
            schema: { type: 'integer', minimum: 1, maximum: 100 },
          },
        }),
      after: ((schema) =>
        z.union([schema, z.preprocess((val) => (val === 'null' ? null : val), schema)]))(
        z.union([
          z.string().openapi({ example: 'whe_123' }),
          z.preprocess((val) => (val === 'null' ? null : val), z.null().nullable()),
        ]),
      )
        .exactOptional()
        .openapi({
          param: {
            name: 'after',
            in: 'query',
            description: 'ID of the last webhook endpoint from the previous page.',
            required: false,
            schema: { anyOf: [{ example: 'whe_123', type: 'string' }, { type: 'null' }] },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success',
      content: { 'application/json': { schema: WebhookEndpointListResourceSchema } },
    },
    400: {
      description: 'The request parameters are invalid.',
      content: { 'application/json': { schema: ErrorResponseSchema } },
    },
    404: {
      description:
        'The pagination cursor does not identify a webhook endpoint in the authenticated project.',
      content: { 'application/json': { schema: ErrorResponseSchema } },
    },
  },
})

